   311→      let color = '#ffffff';
   312→      if (entry.rank === 1) color = '#FFD700'; // 금색
   313→      else if (entry.rank === 2) color = '#C0C0C0'; // 은색
   314→      else if (entry.rank === 3) color = '#CD7F32'; // 동색
